import { Request, Response, NextFunction } from 'express';
import { ZodError } from 'zod';
import { Prisma } from '@prisma/client';
import jwt from 'jsonwebtoken';
import logger from '../logger.js';

/**
 * Custom error classes for better error handling
 */
export class AppError extends Error {
  statusCode: number;
  isOperational: boolean;
  code?: string;

  constructor(message: string, statusCode: number, code?: string) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    this.code = code;
    Error.captureStackTrace(this, this.constructor);
  }
}

export class ValidationError extends AppError {
  constructor(message: string) {
    super(message, 400, 'VALIDATION_ERROR');
  }
}

export class AuthenticationError extends AppError {
  constructor(message: string = 'Authentication failed') {
    super(message, 401, 'AUTHENTICATION_ERROR');
  }
}

export class AuthorizationError extends AppError {
  constructor(message: string = 'Insufficient permissions') {
    super(message, 403, 'AUTHORIZATION_ERROR');
  }
}

export class NotFoundError extends AppError {
  constructor(message: string = 'Resource not found') {
    super(message, 404, 'NOT_FOUND');
  }
}

export class ConflictError extends AppError {
  constructor(message: string = 'Resource conflict') {
    super(message, 409, 'CONFLICT');
  }
}

export class RateLimitError extends AppError {
  constructor(message: string = 'Too many requests') {
    super(message, 429, 'RATE_LIMIT');
  }
}

/**
 * Async error wrapper for route handlers
 */
export function asyncHandler(fn: Function) {
  return (req: Request, res: Response, next: NextFunction) => {
    Promise.resolve(fn(req, res, next)).catch(next);
  };
}

/**
 * 404 Not Found handler
 */
export function notFoundHandler(req: Request, res: Response, next: NextFunction): void {
  const error = new NotFoundError(`Route ${req.method} ${req.path} not found`);
  next(error);
}

/**
 * Development error response with stack trace
 */
function sendErrorDev(err: any, req: Request, res: Response) {
  const statusCode = err.statusCode || 500;
  
  logger.error({
    error: err,
    request: {
      method: req.method,
      url: req.url,
      headers: req.headers,
      body: req.body,
      query: req.query,
      params: req.params,
      ip: req.ip,
      user: req.user,
    },
  }, 'Request error');

  res.status(statusCode).json({
    status: 'error',
    error: err,
    message: err.message,
    stack: err.stack,
    code: err.code,
  });
}

/**
 * Production error response without sensitive details
 */
function sendErrorProd(err: any, req: Request, res: Response) {
  const statusCode = err.statusCode || 500;
  
  // Operational, trusted error: send message to client
  if (err.isOperational) {
    logger.warn({
      error: {
        message: err.message,
        code: err.code,
        statusCode: err.statusCode,
      },
      request: {
        method: req.method,
        url: req.url,
        ip: req.ip,
        userId: req.user?.id,
      },
    }, 'Operational error');

    res.status(statusCode).json({
      status: 'error',
      message: err.message,
      code: err.code,
    });
  } else {
    // Programming or other unknown error: don't leak error details
    logger.error({
      error: err,
      request: {
        method: req.method,
        url: req.url,
        headers: req.headers,
        body: req.body,
        ip: req.ip,
        userId: req.user?.id,
      },
    }, 'Unexpected error');

    res.status(500).json({
      status: 'error',
      message: 'Something went wrong',
      code: 'INTERNAL_ERROR',
    });
  }
}

/**
 * Handle specific error types
 */
function handleSpecificErrors(err: any): AppError {
  // Zod validation errors
  if (err instanceof ZodError) {
    const errors = err.errors.map(e => ({
      field: e.path.join('.'),
      message: e.message,
    }));
    
    return new ValidationError(
      `Validation failed: ${errors.map(e => `${e.field}: ${e.message}`).join(', ')}`
    );
  }

  // Prisma errors
  if (err instanceof Prisma.PrismaClientKnownRequestError) {
    switch (err.code) {
      case 'P2002':
        const field = err.meta?.target as string[];
        return new ConflictError(
          `Duplicate value for field: ${field?.join(', ') || 'unknown'}`
        );
      case 'P2025':
        return new NotFoundError('Record not found');
      case 'P2003':
        return new ValidationError('Foreign key constraint failed');
      default:
        return new AppError('Database error', 400, err.code);
    }
  }

  if (err instanceof Prisma.PrismaClientValidationError) {
    return new ValidationError('Invalid data provided');
  }

  // JWT errors
  if (err instanceof jwt.TokenExpiredError) {
    return new AuthenticationError('Token has expired');
  }

  if (err instanceof jwt.JsonWebTokenError) {
    return new AuthenticationError('Invalid token');
  }

  // CORS errors
  if (err.message === 'Not allowed by CORS') {
    return new AppError('Cross-origin request blocked', 403, 'CORS_ERROR');
  }

  // File upload errors
  if (err.message && err.message.includes('File too large')) {
    return new ValidationError('File size exceeds maximum allowed size');
  }

  if (err.message && err.message.includes('Invalid file type')) {
    return new ValidationError('File type not allowed');
  }

  // MongoDB/Mongoose-like errors (if using)
  if (err.name === 'CastError') {
    return new ValidationError(`Invalid ${err.path}: ${err.value}`);
  }

  if (err.code === 11000) {
    const field = Object.keys(err.keyValue)[0];
    return new ConflictError(`Duplicate field value: ${field}`);
  }

  if (err.name === 'ValidationError') {
    const errors = Object.values(err.errors as any).map(
      (e: any) => e.message
    );
    return new ValidationError(`Validation failed: ${errors.join(', ')}`);
  }

  return err;
}

/**
 * Global error handling middleware
 */
export function errorHandler(
  err: Error,
  req: Request,
  res: Response,
  next: NextFunction
): void {
  // Handle specific error types
  let error = handleSpecificErrors(err);

  // Set default values if not set
  error.statusCode = error.statusCode || 500;

  // Send appropriate error response
  if (process.env.NODE_ENV === 'development') {
    sendErrorDev(error, req, res);
  } else {
    sendErrorProd(error, req, res);
  }
}

/**
 * Uncaught exception handler
 */
export function handleUncaughtException(): void {
  process.on('uncaughtException', (error: Error) => {
    logger.fatal({ error }, 'Uncaught Exception');
    
    // Give logger time to write
    setTimeout(() => {
      process.exit(1);
    }, 1000);
  });
}

/**
 * Unhandled rejection handler
 */
export function handleUnhandledRejection(): void {
  process.on('unhandledRejection', (reason: any, promise: Promise<any>) => {
    logger.fatal({ reason, promise }, 'Unhandled Rejection');
    
    // Give logger time to write
    setTimeout(() => {
      process.exit(1);
    }, 1000);
  });
}

/**
 * Graceful shutdown handler
 */
export function handleGracefulShutdown(server: any): void {
  const shutdown = (signal: string) => {
    logger.info(`${signal} received. Starting graceful shutdown...`);
    
    server.close(() => {
      logger.info('HTTP server closed');
      
      // Close database connections
      prisma.$disconnect()
        .then(() => {
          logger.info('Database connections closed');
          process.exit(0);
        })
        .catch((err) => {
          logger.error({ error: err }, 'Error closing database connections');
          process.exit(1);
        });
    });

    // Force shutdown after 30 seconds
    setTimeout(() => {
      logger.error('Could not close connections in time, forcefully shutting down');
      process.exit(1);
    }, 30000);
  };

  process.on('SIGTERM', () => shutdown('SIGTERM'));
  process.on('SIGINT', () => shutdown('SIGINT'));
}

/**
 * Request timeout middleware
 */
export function requestTimeout(timeoutMs: number = 30000) {
  return (req: Request, res: Response, next: NextFunction) => {
    const timeout = setTimeout(() => {
      logger.warn({
        method: req.method,
        url: req.url,
        ip: req.ip,
        userId: req.user?.id,
      }, 'Request timeout');
      
      res.status(408).json({
        status: 'error',
        message: 'Request timeout',
        code: 'REQUEST_TIMEOUT',
      });
    }, timeoutMs);

    res.on('finish', () => clearTimeout(timeout));
    res.on('close', () => clearTimeout(timeout));
    
    next();
  };
}